export const humanFileSize = (size: number): string => {
  const KB = 1024;
  const MB = KB * KB;
  if (size >= MB) return Math.round(size / MB) + " MB";
  if (size >= KB) return Math.ceil(size / KB) + " KB";
  return size + " B";
};

def pretty_size(num_bytes: int) -> str:
    if num_bytes < 1024:
        return f"{num_bytes} B"
    if num_bytes < 1024 * 1024:
        return f"{math.ceil(num_bytes / 1024)} KB"
    return f"{round(num_bytes / (1024 * 1024))} MB"

function forwardCancellation(parent: AbortSignal | undefined, child: AbortController) {
  if (parent === undefined) return () => {};
  const relay = () => child.abort(parent.reason);
  if (parent.aborted) {
    relay();
    return () => {};
  }
  parent.addEventListener("abort", relay, { once: true });
  return function unlink() {
    parent.removeEventListener("abort", relay);
  };
}

const ENTITIES: Record<string, string> = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };
function htmlEncode(text: string): string {
  let out = "";
  for (const ch of text) {
    out += ENTITIES[ch] ?? ch;
  }
  return out;
}

function fitCanvasToWindow() {
  const ratio = Math.min(window.devicePixelRatio || 1, 2);
  w = window.innerWidth;
  h = window.innerHeight;
  canvas.width = Math.round(w * ratio);
  canvas.height = Math.round(h * ratio);
  context.setTransform(ratio, 0, 0, ratio, 0, 0);
}

private addUsage(u: ChatUsage) {
  const prev = this.totals ?? { promptTokens: 0, completionTokens: 0, totalTokens: 0, requestCount: 0 };
  const prompt = u.promptTokens ?? 0;
  const completion = u.completionTokens ?? 0;
  this.totals = {
    promptTokens: prev.promptTokens + prompt,
    completionTokens: prev.completionTokens + completion,
    totalTokens: prev.totalTokens + (u.totalTokens ?? prompt + completion),
    requestCount: prev.requestCount + 1
  };
}

