async function askYesNo(prompt: string) {
  const io = createInterface({ input: stdin, output: stdout });
  try {
    const reply = await io.question(prompt + " (y/N): ");
    return /^y(es)?$/i.test(reply.trim());
  } finally {
    io.close();
  }
}

function freeServerKey(wanted: string, existing: McpServersConfig): string {
  const base = wanted.trim().split(/\s+/).join("-") || "proposed-tool";
  let key = base;
  let n = 1;
  while (key in existing) {
    n += 1;
    key = `${base}-${n}`;
  }
  return key;
}
